import React from "react";
import BigBangImage from "./bigBang.png";

function Section2() {
  const title = (
    <h1 className=" text-yellow-500 relative text-3xl font-poppins mb-10">
      Formation and Early Evolution
    </h1>
  );

  const body = (
    <p className=" text-white font-poppin ">
      The solar system was born about 4.6 billion years ago from a massive cloud
      of gas and dust, known as the solar nebula, which collapsed under its own
      gravity. This collapse led to the formation of a rotating disk, with the
      Sun forming at its center as nuclear fusion ignited. The remaining
      material in the disk gradually coalesced into planetesimals, which grew
      into planets. The inner solar system, where it was too hot for volatile
      compounds to remain solid, formed rocky planets like Earth, while the
      outer regions gave rise to gas giants like Jupiter and Saturn. The early
      solar system was chaotic, with frequent collisions shaping planets,
      forming moons, and creating craters. Over time, the solar system
      stabilized, paving the way for the emergence of life on Earth.
    </p>
  );
  return (
    <>
      <div className="  w-full h-screen p-10 md:flex md:p-1 ">
        <div className=" text-center p-3 text-xl md:w-1/2 ">
          {title}
          
          {body}
        </div>
        <div  className=" md:w-1/2  ">
        <video src=""></video>
          {/* <img src={BigBangImage} alt="" srcset="" className=" md:h-screen" /> */}
        </div>
        
      </div>
    </>
  );
}

export default Section2;
